def build_ibt_academic_reading(pack_num: int) -> tuple[list[dict], list[dict]]:
    """Builds 3 Academic passages + 15 MCQs (Q036..Q050) for pack 1..5."""
    passages = []
    questions = []
    q_idx = 36
    for p_ord, (pid_sfx, title, body, qlist) in enumerate(_ACAD[pack_num], start=1):
        pid = f"IBT0{pack_num}-{pid_sfx}"
        assert len(qlist) == 5, f"{pid} expected 5 questions"
        passages.append({
            "id": pid,
            "title": title,
            "body": body,
            "readingOrder": 7 + p_ord,
        })
        for sub_i, (qtext, opts, cidx, mod, diff, exp) in enumerate(qlist, start=1):
            qid = f"IBT26-0{pack_num}-Q{q_idx:03d}"
            questions.append(
                rotated_mcq(
                    qid=qid,
                    section="READING",
                    prompt=f"Academic Passage {p_ord} ('{title}' — Q{sub_i}/5): {qtext}",
                    options=opts,
                    correct_idx=cidx,
                    explanation=exp,
                    rationale_source=mod,
                    difficulty=diff,
                    seed=pack_num * 19 + q_idx,
                    passage_id=pid,
                ),
            )
            q_idx += 1
    assert len(questions) == 15
    return passages, questions
